}
.reveal-slide .rs-features[data-cols="1"] { --rs-feat-cols: 1; }
.reveal-slide .rs-features[data-cols="2"] { --rs-feat-cols: 2; }
.reveal-slide .rs-features[data-cols="4"] { --rs-feat-cols: 4; }
