.reveal-slide .rs-quote { border: 0; padding: 0; margin: 0; }
.reveal-slide .rs-quote[data-variant="accent"] {
  background: var(--color-accent, #08bdba); color: var(--color-background, #fff);
  padding: 32px; border-radius: 16px;
}
