animation_ir.css:
@keyframes ir-fade-up { from { opacity: 0; transform: translate3d(0, 16px, 0); } to { opacity: 1; transform: translate3d(0, 0, 0); } }
@keyframes ir-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes ir-count-up { from { opacity: 0.85; } to { opacity: 1; } }
@keyframes ir-pulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.04); } }
.ir-anim-entry-headline { animation: ir-fade-up 0.440s ease-out 0.080s 1 both; }
.ir-anim-entry-subheadline { animation: ir-fade 0.360s linear 0.200s 1 both; }
